def artwork_trash_settings(conn) -> dict[str, Any]:
    enabled = bool(app_setting_value(conn, "artwork_trash_purge_enabled", False))
    retention = clean_text(app_setting_value(conn, "artwork_trash_retention", "7d")) or "7d"
    if retention not in ARTWORK_TRASH_RETENTION_OPTIONS:
        retention = "7d"
    option = ARTWORK_TRASH_RETENTION_OPTIONS[retention]
    return {
        "purgeEnabled": enabled,
        "retention": retention,
        "retentionSeconds": option["seconds"],
        "retentionInterval": option["interval"],
        "options": [
            {"value": key, "seconds": value["seconds"], "interval": value["interval"]}
            for key, value in ARTWORK_TRASH_RETENTION_OPTIONS.items()
        ],
    }


def delete_local_media_asset_file(asset: dict[str, Any]) -> bool:
    if clean_text(asset.get("storage_backend")) != "local":
        return False
    storage_key = clean_text(asset.get("storage_key"))
    if not storage_key:
        return False
    data_dir = legacy_data_dir().resolve()
    target = (data_dir / storage_key).resolve()
    try:
        target.relative_to(data_dir)
    except ValueError:
        return False
    if not target.is_file():
        return False
    target.unlink()
    return True


def purge_expired_artwork_trash(conn) -> dict[str, Any]:
    if not table_exists(conn, "entity_media") or not table_exists(conn, "media_assets"):
        return {"purgedLinks": 0, "purgedAssets": 0, "purgedFiles": 0}
    with conn.cursor() as cur:
        cur.execute(
            """
            DELETE FROM entity_media
            WHERE deleted_at IS NOT NULL
              AND purge_after IS NOT NULL
              AND purge_after <= now()
            RETURNING media_id
            """
        )
        deleted_media_ids = [row["media_id"] for row in cur.fetchall()]
        purged_assets = 0
        purged_files = 0
        for media_id in deleted_media_ids:
            cur.execute("SELECT COUNT(*)::int AS refs FROM entity_media WHERE media_id=%s", (media_id,))
            if int((cur.fetchone() or {}).get("refs") or 0) > 0:
                continue
            cur.execute(
                """
                DELETE FROM media_assets
                WHERE id=%s
                  AND kind IN ('poster', 'backdrop')
                RETURNING id, storage_backend, storage_key
                """,
                (media_id,),
            )
            asset = cur.fetchone()
            if not asset:
                continue
            purged_assets += 1
            try:
                if delete_local_media_asset_file(asset):
                    purged_files += 1
            except OSError:
                pass
    return {"purgedLinks": len(deleted_media_ids), "purgedAssets": purged_assets, "purgedFiles": purged_files}


def artwork_trash_entries(conn, *, limit: int = 200) -> dict[str, Any]:
    if not table_exists(conn, "entity_media") or not table_exists(conn, "media_assets"):
        return {"items": [], "settings": artwork_trash_settings(conn), "purge": {"purgedLinks": 0, "purgedAssets": 0, "purgedFiles": 0}}
    purge = purge_expired_artwork_trash(conn)
    settings = artwork_trash_settings(conn)
    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT
                em.entity_type,
                em.entity_id,
                em.media_id,
                em.role,
                em.deleted_at,
                em.deleted_by,
                em.purge_after,
                em.restore_metadata,
                EXTRACT(EPOCH FROM (em.purge_after - now()))::int AS purge_in_seconds,
                ma.kind,
                ma.variant,
                ma.storage_backend,
                ma.storage_key,
                ma.source_url,
                ma.provider_id,
                ma.content_type,
                ma.width,
                ma.height,
                ma.size_bytes,
                ma.sha256,
                ma.metadata,
                COALESCE(m.title, c.title) AS entity_title,
                m.year AS movie_year,
                c.container_type,
                u.username AS deleted_by_username,
                u.display_name AS deleted_by_display_name
            FROM entity_media em
            JOIN media_assets ma ON ma.id = em.media_id
            LEFT JOIN movies m ON em.entity_type='movie' AND m.id = em.entity_id
            LEFT JOIN containers c ON em.entity_type='container' AND c.id = em.entity_id
            LEFT JOIN users u ON u.id = em.deleted_by
            WHERE em.deleted_at IS NOT NULL
              AND ma.kind IN ('poster', 'backdrop')
            ORDER BY em.deleted_at DESC
            LIMIT %s
            """,
            (min(max(int(limit or 200), 1), 500),),
        )
        rows = cur.fetchall()
    items = []
    for row in rows:
        row["url"] = media_asset_public_url(row)
        purge_seconds = row.get("purge_in_seconds")
        if purge_seconds is not None:
            purge_seconds = max(int(purge_seconds), 0)
        items.append(
            {
                "entityType": row.get("entity_type"),
                "entityId": row.get("entity_id"),
                "entityTitle": row.get("entity_title") or "-",
                "movieYear": row.get("movie_year"),
                "containerType": row.get("container_type"),
                "mediaId": row.get("media_id"),
                "kind": row.get("kind"),
                "role": row.get("role"),
                "deletedAt": row.get("deleted_at"),
                "deletedBy": row.get("deleted_by"),
                "deletedByUsername": row.get("deleted_by_username") or row.get("deleted_by_display_name"),
                "purgeAfter": row.get("purge_after"),
                "purgeInSeconds": purge_seconds,
                "purgeEnabled": bool(row.get("purge_after")),
                "restoreMetadata": row.get("restore_metadata") or {},
                "media": {
                    "id": row.get("media_id"),
                    "kind": row.get("kind"),
                    "variant": row.get("variant"),
                    "storage_backend": row.get("storage_backend"),
                    "storage_key": row.get("storage_key"),
                    "source_url": row.get("source_url"),
                    "provider_id": row.get("provider_id"),
                    "content_type": row.get("content_type"),
                    "width": row.get("width"),
                    "height": row.get("height"),
                    "size_bytes": row.get("size_bytes"),
                    "sha256": row.get("sha256"),
                    "metadata": row.get("metadata") or {},
                    "url": row.get("url"),
                },
            }
        )
    return {"items": items, "settings": settings, "purge": purge}


def delete_entity_artwork_media_asset(
    conn,
    *,
    entity_type: str,
    entity_id: UUID,
    media_id: UUID,
    kind: str,
    actor: dict[str, Any] | None = None,
) -> dict[str, Any]:
    if entity_type not in {"movie", "container"}:
        raise NextApiError("entityType must be movie or container", 400)
    if kind not in MOVIE_ARTWORK_KINDS:
        raise NextApiError("kind must be poster or backdrop", 400)
    entity_table = "movies" if entity_type == "movie" else "containers"
    if not table_exists(conn, entity_table) or not table_exists(conn, "entity_media") or not table_exists(conn, "media_assets"):
        raise NextApiError("Media asset tables are not available", 503)

    with conn.cursor() as cur:
        cur.execute(f"SELECT id FROM {entity_table} WHERE id=%s", (entity_id,))
        if not cur.fetchone():
            raise NextApiError("Movie not found" if entity_type == "movie" else "Container not found", 404)
        cur.execute(
            """
            SELECT
                ma.id,
                ma.kind,
                ma.variant,
                ma.storage_backend,
                ma.storage_key,
                ma.source_url,
                ma.provider_id,
                ma.content_type,
                ma.width,
                ma.height,
                ma.size_bytes,
                ma.sha256,
                ma.metadata,
                em.role,
                em.is_primary,
                em.sort_order
            FROM entity_media em
            JOIN media_assets ma ON ma.id = em.media_id
            WHERE em.entity_type=%s
              AND em.entity_id=%s
              AND em.media_id=%s
              AND em.role=%s
              AND ma.kind=%s
              AND em.deleted_at IS NULL
            """,
            (entity_type, entity_id, media_id, kind, kind),
        )
        deleted_media = cur.fetchone()
        if not deleted_media:
            raise NextApiError("Media asset is not linked to this item", 404)
        was_primary = bool(deleted_media.get("is_primary"))
        settings = artwork_trash_settings(conn)
        actor_id = actor.get("id") if actor else None
        cur.execute(
            """
            UPDATE entity_media
            SET deleted_at=now(),
                deleted_by=%s,
                purge_after=CASE WHEN %s THEN now() + (%s)::interval ELSE NULL END,
                is_primary=false,
                restore_metadata=%s
            WHERE entity_type=%s
              AND entity_id=%s
              AND media_id=%s
              AND role=%s
              AND deleted_at IS NULL
            RETURNING deleted_at, purge_after
            """,
            (
                actor_id,
                settings["purgeEnabled"],
                settings["retentionInterval"],
                Jsonb(json_ready({"wasPrimary": was_primary, "sortOrder": deleted_media.get("sort_order")})),
                entity_type,
                entity_id,
                media_id,
                kind,
            ),
        )
        trash_row = cur.fetchone()
        if not trash_row:
            raise NextApiError("Media asset is not linked to this item", 404)
        deleted_links = 1

        replacement = None
        if was_primary:
            cur.execute(
                """
                SELECT
                    ma.id,
                    ma.kind,
                    ma.variant,
                    ma.storage_backend,
                    ma.storage_key,
                    ma.source_url,
                    ma.provider_id,
                    ma.content_type,
                    ma.width,
                    ma.height,
                    ma.size_bytes,
                    ma.sha256,
                    ma.metadata,
                    em.role,
                    em.is_primary,
                    em.sort_order
                FROM entity_media em
                JOIN media_assets ma ON ma.id = em.media_id
                WHERE em.entity_type=%s
                  AND em.entity_id=%s
                  AND em.role=%s
                  AND ma.kind=%s
                  AND em.deleted_at IS NULL
                ORDER BY em.sort_order, ma.created_at
                LIMIT 1
                """,
                (entity_type, entity_id, kind, kind),
            )
            replacement = cur.fetchone()
            if replacement:
                cur.execute(
                    """
                    UPDATE entity_media
                    SET is_primary=true,
                        sort_order=0
                    WHERE entity_type=%s
                      AND entity_id=%s
                      AND media_id=%s
                      AND role=%s
                    """,
                    (entity_type, entity_id, replacement["id"], kind),
                )
                replacement["is_primary"] = True
                replacement["sort_order"] = 0
                replacement["url"] = media_asset_public_url(replacement)
                metadata_patch = {f"{kind}_url": replacement["url"], f"{kind}_locked": True}
            else:
                metadata_patch = {f"{kind}_url": None, f"{kind}_locked": False}
            cur.execute(
                f"UPDATE {entity_table} SET metadata=metadata || %s, updated_at=now() WHERE id=%s",
                (Jsonb(json_ready(metadata_patch)), entity_id),
            )
        else:
            cur.execute(f"UPDATE {entity_table} SET updated_at=now() WHERE id=%s", (entity_id,))

    revision = 0
    operation = f"{entity_type}.media_trashed"
    payload = {
        f"{entity_type}Id": str(entity_id),
        "operation": operation,
        "kind": kind,
        "mediaId": str(media_id),
        "wasPrimary": was_primary,
        "replacementMediaId": str(replacement["id"]) if replacement else None,
        "purgeEnabled": settings["purgeEnabled"],
        "purgeAfter": trash_row.get("purge_after"),
        "actor": actor_job_payload(actor or {}) if actor else None,
    }
    if entity_type == "movie":
        revision = record_sync_change(conn, entity_id, payload)

    deleted_media["url"] = media_asset_public_url(deleted_media)
    return {
        f"{entity_type}Id": str(entity_id),
        "kind": kind,
        "mediaId": str(media_id),
        "deleted": deleted_media,
        "deletedLinks": deleted_links,
        "trashed": True,
        "purgeAfter": trash_row.get("purge_after"),
        "purgeEnabled": settings["purgeEnabled"],
        "replacement": replacement,
        "revision": revision,
    }


def restore_entity_artwork_media_asset(
    conn,
    *,
    entity_type: str,
    entity_id: UUID,
    media_id: UUID,
    actor: dict[str, Any] | None = None,
) -> dict[str, Any]:
    if entity_type not in {"movie", "container"}:
        raise NextApiError("entityType must be movie or container", 400)
    entity_table = "movies" if entity_type == "movie" else "containers"
    if not table_exists(conn, entity_table) or not table_exists(conn, "entity_media") or not table_exists(conn, "media_assets"):
        raise NextApiError("Media asset tables are not available", 503)
    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT
                ma.id,
                ma.kind,
                ma.variant,
                ma.storage_backend,
                ma.storage_key,
                ma.source_url,
                ma.provider_id,
                ma.content_type,
                ma.width,
                ma.height,
                ma.size_bytes,
                ma.sha256,
                ma.metadata,
                em.role,
                em.is_primary,
                em.sort_order,
                em.restore_metadata
            FROM entity_media em
            JOIN media_assets ma ON ma.id = em.media_id
            WHERE em.entity_type=%s
              AND em.entity_id=%s
              AND em.media_id=%s
              AND em.deleted_at IS NOT NULL
              AND ma.kind IN ('poster', 'backdrop')
            """,
            (entity_type, entity_id, media_id),
        )
        media = cur.fetchone()
        if not media:
            raise NextApiError("Deleted artwork was not found", 404)
        kind = media["kind"]
        restore_metadata = media.get("restore_metadata") if isinstance(media.get("restore_metadata"), dict) else {}
        cur.execute(
            """
            SELECT COUNT(*)::int AS primary_count
            FROM entity_media em
            JOIN media_assets ma ON ma.id = em.media_id
            WHERE em.entity_type=%s
              AND em.entity_id=%s
              AND em.deleted_at IS NULL
              AND em.is_primary=true
              AND ma.kind=%s
            """,
            (entity_type, entity_id, kind),
        )
        has_primary = int((cur.fetchone() or {}).get("primary_count") or 0) > 0
        make_primary = bool(restore_metadata.get("wasPrimary")) and not has_primary
        sort_order = int(restore_metadata.get("sortOrder") or media.get("sort_order") or (0 if make_primary else 1))
        cur.execute(
            """
            UPDATE entity_media
            SET deleted_at=NULL,
                deleted_by=NULL,
                purge_after=NULL,
                is_primary=%s,
                sort_order=%s,
                restore_metadata='{}'::jsonb
            WHERE entity_type=%s
              AND entity_id=%s
              AND media_id=%s
              AND role=%s
            """,
            (make_primary, 0 if make_primary else sort_order, entity_type, entity_id, media_id, media.get("role") or kind),
        )
        metadata_patch: dict[str, Any] = {}
        if make_primary:
            metadata_patch = {f"{kind}_url": media_asset_public_url(media), f"{kind}_locked": True}
        if metadata_patch:
            cur.execute(
                f"UPDATE {entity_table} SET metadata=metadata || %s, updated_at=now() WHERE id=%s",
                (Jsonb(json_ready(metadata_patch)), entity_id),
            )
        else:
            cur.execute(f"UPDATE {entity_table} SET updated_at=now() WHERE id=%s", (entity_id,))
    revision = 0
    if entity_type == "movie":
        revision = record_sync_change(
            conn,
            entity_id,
            {
                "movieId": str(entity_id),
                "operation": "movie.media_restored",
                "kind": kind,
                "mediaId": str(media_id),
                "primary": make_primary,
                "actor": actor_job_payload(actor or {}) if actor else None,
            },
        )
    media["url"] = media_asset_public_url(media)
    media["is_primary"] = make_primary
    media["sort_order"] = 0 if make_primary else sort_order
    return {
        f"{entity_type}Id": str(entity_id),
        "kind": kind,
        "mediaId": str(media_id),
        "media": media,
        "restored": True,
        "primary": make_primary,
        "revision": revision,
    }


def container_entity(conn, container_id: UUID) -> dict[str, Any] | None:
    if not table_exists(conn, "containers"):
        return None
    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT
                id,
                public_id,
                container_type,
                title,
                barcode,
                badge_label,
                year,
                description,
                primary_movie_id,
                metadata,
                created_at,
                updated_at
            FROM containers
            WHERE id=%s
            """,
            (container_id,),
        )
        return with_legacy_metadata_media_urls(cur.fetchone())


def container_identifier_entities(conn, container_id: UUID) -> list[dict[str, Any]]:
    if not table_exists(conn, "container_identifiers"):
        return []
    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT provider_id, identifier_type, identifier, created_at
            FROM container_identifiers
            WHERE container_id=%s
            ORDER BY provider_id, identifier_type, identifier
            """,
            (container_id,),
        )
        return cur.fetchall()


def container_member_movie_entities(conn, container_id: UUID, actor: dict[str, Any] | None = None) -> list[dict[str, Any]]:
    if not table_exists(conn, "container_movies") or not table_exists(conn, "movies"):
        return []
    visibility_where, visibility_params = visible_movie_where_sql(conn, actor, "m") if actor else ("TRUE", [])
    with conn.cursor() as cur:
        cur.execute(
            f"""
            SELECT
                m.id,
                m.public_id,
                m.barcode,
                m.title,
                m.sort_title,
                m.original_title,
                m.year,
                m.release_date,
                m.format,
                m.edition,
                m.edition_type,
                m.country,
                m.language,
                m.runtime_minutes,
                m.overview,
                m.rating,
                m.metadata,
                m.created_at,
                m.updated_at,
                m.metadata->>'poster_url' AS poster_url,
                m.metadata->>'backdrop_url' AS backdrop_url,
                cm.sort_order,
                cm.created_at AS linked_at
            FROM container_movies cm
            JOIN movies m ON m.id = cm.movie_id
            WHERE cm.container_id=%s
              AND {visibility_where}
            ORDER BY cm.sort_order, lower(COALESCE(m.sort_title, m.title)), m.year NULLS LAST
            """,
            (container_id, *visibility_params),
        )
        return cur.fetchall()


def collection_item_entities(conn, container_id: UUID, actor: dict[str, Any] | None = None) -> list[dict[str, Any]]:
    if not table_exists(conn, "collection_items"):
        return []
    items: list[dict[str, Any]] = []
    if table_exists(conn, "movies"):
        visibility_where, visibility_params = visible_movie_where_sql(conn, actor, "m") if actor else ("TRUE", [])
        with conn.cursor() as cur:
            cur.execute(
                f"""
                SELECT
                    ci.item_type,
                    ci.item_id,
                    ci.sort_order,
                    ci.created_at AS linked_at,
                    'movie' AS entity_type,
                    m.id AS entity_id,
                    m.public_id,
                    m.barcode,
                    m.title,
                    m.sort_title,
                    m.original_title,
                    m.year,
                    m.format,
                    m.edition,
                    m.metadata,
                    m.metadata->>'poster_url' AS poster_url,
                    m.metadata->>'backdrop_url' AS backdrop_url
                FROM collection_items ci
                JOIN movies m ON m.id = ci.item_id
                WHERE ci.collection_id=%s AND ci.item_type='movie'
                  AND {visibility_where}
                ORDER BY ci.sort_order, lower(COALESCE(m.sort_title, m.title)), m.year NULLS LAST
                """,
                (container_id, *visibility_params),
            )
            items.extend(cur.fetchall())
    if table_exists(conn, "containers"):
        visibility_where, visibility_params = visible_container_where_sql(conn, actor, "c") if actor else ("TRUE", [])
        with conn.cursor() as cur:
            cur.execute(
                f"""
                SELECT
                    ci.item_type,
                    ci.item_id,
                    ci.sort_order,
                    ci.created_at AS linked_at,
                    'container' AS entity_type,
                    c.id AS entity_id,
                    c.public_id,
                    c.container_type,
                    c.barcode,
                    c.badge_label,
                    c.title,
                    c.year,
                    c.description,
                    c.metadata,
                    c.metadata->>'poster_url' AS poster_url,
                    c.metadata->>'backdrop_url' AS backdrop_url
                FROM collection_items ci
                JOIN containers c ON c.id = ci.item_id
                WHERE ci.collection_id=%s AND ci.item_type <> 'movie'
                  AND {visibility_where}
                ORDER BY ci.sort_order, c.container_type, lower(c.title)
                """,
                (container_id, *visibility_params),
            )
            items.extend(cur.fetchall())
    return sorted(items, key=lambda item: (item.get("sort_order") or 0, str(item.get("title") or "").lower()))


def container_aggregate_movie_entities(
    conn,
    container_id: UUID,
    *,
    max_depth: int = 4,
    actor: dict[str, Any] | None = None,
) -> list[dict[str, Any]]:
    if (
        not table_exists(conn, "containers")
        or not table_exists(conn, "movies")
        or not table_exists(conn, "container_movies")
        or not table_exists(conn, "collection_items")
    ):
        return container_member_movie_entities(conn, container_id, actor=actor)
    visibility_where, visibility_params = visible_movie_where_sql(conn, actor, "m") if actor else ("TRUE", [])
    media_join = table_exists(conn, "entity_media") and table_exists(conn, "media_assets")
    media_select = (
        """
                poster_asset.id AS poster_asset_id,
                poster_asset.storage_backend AS poster_asset_storage_backend,
                poster_asset.storage_key AS poster_asset_storage_key,
                poster_asset.source_url AS poster_asset_source_url,
                backdrop_asset.id AS backdrop_asset_id,
                backdrop_asset.storage_backend AS backdrop_asset_storage_backend,
                backdrop_asset.storage_key AS backdrop_asset_storage_key,
                backdrop_asset.source_url AS backdrop_asset_source_url,
        """
        if media_join
        else """
                NULL AS poster_asset_id,
                NULL AS poster_asset_storage_backend,
                NULL AS poster_asset_storage_key,
                NULL AS poster_asset_source_url,
                NULL AS backdrop_asset_id,
                NULL AS backdrop_asset_storage_backend,
                NULL AS backdrop_asset_storage_key,
                NULL AS backdrop_asset_source_url,
        """
    )
    media_join_sql = (
        """
                LEFT JOIN LATERAL (
                    SELECT ma.id, ma.storage_backend, ma.storage_key, ma.source_url
                    FROM entity_media em
                    JOIN media_assets ma ON ma.id = em.media_id
                    WHERE em.entity_type='movie'
                      AND em.entity_id=m.id
                      AND em.deleted_at IS NULL
                      AND ma.kind='poster'
                    ORDER BY em.is_primary DESC, em.sort_order, ma.created_at
                    LIMIT 1
                ) poster_asset ON true
                LEFT JOIN LATERAL (
                    SELECT ma.id, ma.storage_backend, ma.storage_key, ma.source_url
                    FROM entity_media em
                    JOIN media_assets ma ON ma.id = em.media_id
                    WHERE em.entity_type='movie'
                      AND em.entity_id=m.id
                      AND em.deleted_at IS NULL
                      AND ma.kind='backdrop'
                    ORDER BY em.is_primary DESC, em.sort_order, ma.created_at
                    LIMIT 1
                ) backdrop_asset ON true
        """
        if media_join
        else ""
    )
    with conn.cursor() as cur:
        cur.execute(
            f"""
            WITH RECURSIVE container_tree(id, depth, path) AS (
                SELECT %s::uuid, 0, ARRAY[%s::uuid]
                UNION ALL
                SELECT ci.item_id, ct.depth + 1, ct.path || ci.item_id
                FROM collection_items ci
                JOIN container_tree ct ON ct.id = ci.collection_id
                WHERE ci.item_type <> 'movie'
                  AND ct.depth < %s
                  AND NOT ci.item_id = ANY(ct.path)
            ),
            movie_links AS (
                SELECT cm.movie_id, ct.depth, cm.sort_order, cm.created_at AS linked_at
                FROM container_tree ct
                JOIN container_movies cm ON cm.container_id = ct.id
                UNION ALL
                SELECT ci.item_id AS movie_id, ct.depth, ci.sort_order, ci.created_at AS linked_at
                FROM container_tree ct
                JOIN collection_items ci ON ci.collection_id = ct.id AND ci.item_type='movie'
            ),
            ranked AS (
                SELECT DISTINCT ON (m.id)
                    m.id,
                    m.public_id,
                    m.barcode,
                    m.title,
                    m.sort_title,
                    m.original_title,
                    m.year,
                    m.release_date,
                    m.format,
                    m.edition,
                    m.edition_type,
                    m.country,
                    m.language,
                    m.runtime_minutes,
                    m.overview,
                    m.rating,
                    m.metadata,
                    m.created_at,
                    m.updated_at,
                    COALESCE(m.metadata->>'poster_url', poster_asset.source_url) AS poster_url,
                    COALESCE(m.metadata->>'backdrop_url', backdrop_asset.source_url) AS backdrop_url,
{media_select}
                    ml.depth,
                    ml.sort_order,
                    ml.linked_at
                FROM movie_links ml
                JOIN movies m ON m.id = ml.movie_id
                {media_join_sql}
                WHERE {visibility_where}
                ORDER BY m.id, ml.depth, ml.sort_order, lower(COALESCE(m.sort_title, m.title))
            )
            SELECT *
            FROM ranked
            ORDER BY depth, sort_order, lower(COALESCE(sort_title, title)), year NULLS LAST
            """,
            (container_id, container_id, max_depth, *visibility_params),
        )
        rows = cur.fetchall()
    return [with_preview_media_urls(row) for row in rows]


def container_aggregate_media_asset_entities(conn, movies: list[dict[str, Any]]) -> list[dict[str, Any]]:
    assets: list[dict[str, Any]] = []
    seen: set[tuple[str, str]] = set()

    def add_asset(asset: dict[str, Any], source_movie: dict[str, Any] | None = None) -> None:
        kind = clean_text(asset.get("kind"))
        url = media_asset_public_url(asset) or server_usable_image(asset.get("url") or asset.get("source_url"))
        if kind not in {"poster", "backdrop"} or not url:
            return
        key = (kind, url)
        if key in seen:
            return
        seen.add(key)
        row = dict(asset)
        row["url"] = url
        if source_movie:
            row["sourceMovieId"] = str(source_movie.get("id") or "")
            row["sourceMovieTitle"] = source_movie.get("title") or source_movie.get("original_title") or ""
            row["sourceMovieReleaseDate"] = source_movie.get("release_date") or ""
            row["sourceMovieYear"] = source_movie.get("year") or ""
            row["sourceMovieSortTitle"] = source_movie.get("sort_title") or source_movie.get("title") or ""
        assets.append(row)

    movie_ids = [movie.get("id") for movie in movies if movie.get("id")]
    movie_by_id = {str(movie.get("id")): movie for movie in movies if movie.get("id")}
    if movie_ids and table_exists(conn, "entity_media") and table_exists(conn, "media_assets"):
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT
                    ma.id,
                    ma.kind,
                    ma.variant,
                    ma.storage_backend,
                    ma.storage_key,
                    ma.source_url,
                    ma.provider_id,
                    ma.content_type,
                    ma.width,
                    ma.height,
                    ma.size_bytes,
                    ma.sha256,
                    ma.metadata,
                    em.role,
                    em.is_primary,
                    em.sort_order,
                    em.entity_id AS source_movie_id,
                    m.title AS source_movie_title,
                    m.sort_title AS source_movie_sort_title,
                    m.release_date AS source_movie_release_date,
                    m.year AS source_movie_year
                FROM entity_media em
                JOIN media_assets ma ON ma.id = em.media_id
                JOIN movies m ON m.id = em.entity_id
                WHERE em.entity_type='movie'
                  AND em.entity_id = ANY(%s)
                  AND em.deleted_at IS NULL
                  AND ma.kind IN ('poster', 'backdrop')
                ORDER BY lower(m.title), ma.kind, em.is_primary DESC, em.sort_order, ma.created_at
                """,
                (movie_ids,),
            )
            for row in cur.fetchall():
                source_movie = movie_by_id.get(str(row.get("source_movie_id"))) or {
                    "id": row.get("source_movie_id"),
                    "title": row.get("source_movie_title"),
                    "sort_title": row.get("source_movie_sort_title"),
                    "release_date": row.get("source_movie_release_date"),
                    "year": row.get("source_movie_year"),
                }
                add_asset(row, source_movie)

    for movie in movies:
        for kind in ("poster", "backdrop"):
            url = server_usable_image(movie.get(f"{kind}_url"))
            if url:
                add_asset(
                    {
                        "id": f"aggregate:{kind}:{movie.get('id')}",
                        "kind": kind,
                        "source_url": url,
                        "provider_id": "aggregate",
                        "is_primary": False,
                    },
                    movie,
                )
    return assets


def container_aggregate_video_entities(movies: list[dict[str, Any]]) -> list[dict[str, Any]]:
    videos: list[dict[str, Any]] = []
    seen: set[str] = set()

    def add_video(movie: dict[str, Any], item: dict[str, Any]) -> None:
        url = clean_text(item.get("url") or item.get("video_url") or item.get("href"))
        if not url or not url.startswith(("http://", "https://")) or url in seen:
            return
        seen.add(url)
        videos.append(
            {
                "label": clean_text(item.get("label") or item.get("name") or item.get("title") or item.get("type")) or "Video",
                "type": clean_text(item.get("type")),
                "source": clean_text(item.get("source") or item.get("provider")),
                "url": url,
                "sourceMovieId": str(movie.get("id") or ""),
                "sourceMovieTitle": movie.get("title") or movie.get("original_title") or "",
                "sourceMovieReleaseDate": movie.get("release_date") or "",
                "sourceMovieYear": movie.get("year") or "",
                "sourceMovieSortTitle": movie.get("sort_title") or movie.get("title") or "",
            }
        )

    for movie in movies:
        metadata = movie.get("metadata") if isinstance(movie.get("metadata"), dict) else {}
        add_video(movie, {"label": "Trailer", "type": "Trailer", "source": "metadata", "url": movie.get("trailer_url") or metadata.get("trailer_url")})
        for item in metadata.get("videos") if isinstance(metadata.get("videos"), list) else []:
            if isinstance(item, dict):
                add_video(movie, item)
    return videos


def container_aggregate_summary(movies: list[dict[str, Any]], assets: list[dict[str, Any]], videos: list[dict[str, Any]]) -> dict[str, Any]:
    years = sorted({int(str(movie.get("year"))) for movie in movies if str(movie.get("year") or "").isdigit()})
    formats = sorted({clean_text(movie.get("format")) for movie in movies if clean_text(movie.get("format"))}, key=str.lower)
    poster_count = len([asset for asset in assets if asset.get("kind") == "poster"])
    backdrop_count = len([asset for asset in assets if asset.get("kind") == "backdrop"])
    return {
        "movieCount": len(movies),
        "memberTitles": [movie.get("title") for movie in movies if movie.get("title")],
        "formats": ", ".join(formats),
        "yearRange": f"{years[0]}-{years[-1]}" if len(years) > 1 else (str(years[0]) if years else ""),
        "posterCount": poster_count,
        "backdropCount": backdrop_count,
        "artwork": f"{poster_count} posters / {backdrop_count} backdrops",
        "videoCount": len(videos),
    }


def refresh_container_metadata(
    conn,
    container_id: UUID,
    *,
    dry_run: bool,
    actor: dict[str, Any] | None = None,
) -> dict[str, Any]:
    container = container_entity(conn, container_id)
    if not container:
        raise NextApiError("Container not found", 404)
    movies = container_aggregate_movie_entities(conn, container_id)
    assets = container_aggregate_media_asset_entities(conn, movies)
    videos = container_aggregate_video_entities(movies)
    summary = container_aggregate_summary(movies, assets, videos)
    metadata = container.get("metadata") if isinstance(container.get("metadata"), dict) else {}
    description = clean_text(container.get("description"))
    generated_description = ""
    if summary.get("memberTitles"):
        titles = ", ".join(summary["memberTitles"][:8])
        suffix = "..." if len(summary["memberTitles"]) > 8 else ""
        generated_description = f"Contains {summary.get('movieCount', 0)} movies: {titles}{suffix}"

    metadata_updates = {
        "aggregate": summary,
        "videos": videos[:80],
    }
    if assets:
        primary_poster = next((asset for asset in assets if asset.get("kind") == "poster"), None)
        primary_backdrop = next((asset for asset in assets if asset.get("kind") == "backdrop"), None)
        if primary_poster and not metadata.get("poster_locked"):
            metadata_updates["poster_url"] = primary_poster.get("url")
        if primary_backdrop and not metadata.get("backdrop_locked"):
            metadata_updates["backdrop_url"] = primary_backdrop.get("url")

    proposal = {
        "containerId": str(container_id),
        "dryRun": dry_run,
        "movieCount": summary.get("movieCount", 0),
        "metadataUpdates": metadata_updates,
        "description": description or generated_description,
    }
    if dry_run:
        return {"dryRun": True, "changed": False, "proposal": proposal, "summary": summary}

    next_metadata = dict(metadata)
    next_metadata.update(metadata_updates)
    with conn.cursor() as cur:
        cur.execute(
            """
            UPDATE containers
            SET metadata=%s,
                description=COALESCE(NULLIF(description, ''), %s),
                updated_at=now()
            WHERE id=%s
            """,
            (Jsonb(json_ready(next_metadata)), generated_description or None, container_id),
        )
    revision = 0
    if table_exists(conn, "sync_changes"):
        revision = next_revision(conn)
        sync_change(
            conn,
            revision=revision,
            entity_type="container",
            entity_id=str(container_id),
            operation="container.metadata_refresh",
            payload={
                "containerId": str(container_id),
                "summary": summary,
                "actor": actor_job_payload(actor or {}) if actor else None,
            },
        )
    return {"dryRun": False, "changed": True, "revision": revision, "applied": proposal, "summary": summary}


def container_detail_entity(conn, container_id: UUID, actor: dict[str, Any] | None = None) -> dict[str, Any] | None:
    container = container_entity(conn, container_id)
    if not container:
        return None
    aggregate_movies = container_aggregate_movie_entities(conn, container_id, actor=actor)
    aggregate_assets = container_aggregate_media_asset_entities(conn, aggregate_movies)
    aggregate_videos = container_aggregate_video_entities(aggregate_movies)
    return {
        "container": container,
        "identifiers": container_identifier_entities(conn, container_id),
        "memberMovies": container_member_movie_entities(conn, container_id, actor=actor),
        "collectionItems": collection_item_entities(conn, container_id, actor=actor),
        "mediaAssets": entity_media_asset_entities(conn, "container", container_id),
        "aggregateMovies": aggregate_movies,
        "aggregateMediaAssets": aggregate_assets,
        "aggregateVideos": aggregate_videos,
        "aggregateSummary": container_aggregate_summary(aggregate_movies, aggregate_assets, aggregate_videos),
    }


def all_movie_entities(conn, *, limit: int = 1000, actor: dict[str, Any] | None = None) -> list[dict[str, Any]]:
    if not table_exists(conn, "movies"):
        return []
    visibility_where, visibility_params = visible_movie_where_sql(conn, actor, "m") if actor else ("TRUE", [])
    with conn.cursor() as cur:
        cur.execute(
            f"""
            SELECT
                m.id,
                m.public_id,
                m.barcode,
                m.title,
                m.sort_title,
                m.original_title,
                m.year,
                m.release_date,
                m.format,
                m.edition,
                m.edition_type,
                m.country,
                m.language,
                m.runtime_minutes,
                m.overview,
                m.notes,
                m.rating,
                m.purchase_date,
                m.purchase_price,
                m.location,
                m.metadata,
                m.created_at,
                m.updated_at
            FROM movies m
            WHERE {visibility_where}
            ORDER BY lower(COALESCE(m.sort_title, m.title)), m.year NULLS LAST
            LIMIT %s
            """,
            (*visibility_params, limit),
        )
        return cur.fetchall()


