def queue_receiver_payload_to_receivers(
    conn,
    *,
    payload: dict[str, Any],
    actor: dict[str, Any] | None = None,
    reason: str = "receiver_payload",
) -> dict[str, Any]:
    receivers = [
        plugin
        for plugin in metadata_receiver_plugins(conn)
        if "receive_metadata" in set(plugin.get("capabilities") or (plugin.get("manifest") or {}).get("capabilities") or [])
    ]
    jobs: list[dict[str, Any]] = []
    if not receivers:
        return {
            "receiverCount": 0,
            "queuedJobs": [],
            "payloadSummary": {
                "entityType": payload.get("entityType"),
                "identity": payload.get("identity"),
                "fieldCount": len(payload.get("payload") or {}),
                "fields": sorted((payload.get("payload") or {}).keys()),
            },
        }
    for plugin in receivers:
        jobs.append(
            create_background_job(
                conn,
                job_type=PLUGIN_EXECUTION_JOB_TYPE,
                payload={
                    "pluginId": plugin["id"],
                    "entrypoint": "receive_metadata",
                    "payload": payload,
                    "requestedBy": actor_job_payload(actor or {}),
                    "reason": reason,
                },
            )
        )
    return {
        "receiverCount": len(receivers),
        "queuedJobs": jobs,
        "payloadSummary": {
            "entityType": payload.get("entityType"),
            "identity": payload.get("identity"),
            "fieldCount": len(payload.get("payload") or {}),
            "fields": sorted((payload.get("payload") or {}).keys()),
            "sourceProviders": ((payload.get("metadata") or {}).get("sourceProviders") or []),
        },
    }


def audit_event(
    conn,
    *,
    event_type: str,
    category: str = "system",
    actor: dict[str, Any] | None = None,
    target_type: str | None = None,
    target_id: Any = None,
    summary: str | None = None,
    metadata: dict[str, Any] | None = None,
) -> None:
    if not table_exists(conn, "audit_events"):
        return
    actor = actor or {}
    with conn.cursor() as cur:
        cur.execute(
            """
            INSERT INTO audit_events (
                event_type,
                category,
                actor_user_id,
                actor_username,
                actor_role,
                target_type,
                target_id,
                summary,
                metadata,
                request_ip,
                user_agent
            )
            VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
            """,
            (
                event_type,
                category,
                actor.get("id"),
                actor.get("username"),
                actor.get("role"),
                target_type,
                str(target_id) if target_id is not None else None,
                summary,
                Jsonb(json_ready(redact_sensitive_payload(metadata or {}))),
                public_request_ip(),
                request.headers.get("User-Agent"),
            ),
        )


def normalize_request_ip_candidate(value: Any) -> str:
    text = str(value or "").strip().strip('"').strip("'")
    if not text:
        return ""
    if text.lower().startswith("for="):
        text = text[4:].strip().strip('"').strip("'")
    if ";" in text:
        text = text.split(";", 1)[0].strip()
    if text.startswith("[") and "]" in text:
        return text[1:text.index("]")].strip()
    if text.count(":") == 1:
        host, port = text.rsplit(":", 1)
        if port.isdigit():
            text = host
    return text.strip()


def public_request_ip() -> str:
    candidates: list[str] = []
    for header in ("CF-Connecting-IP", "True-Client-IP", "X-Real-IP", "X-Client-IP"):
        value = normalize_request_ip_candidate(request.headers.get(header))
        if value:
            candidates.append(value)
    forwarded_for = request.headers.get("X-Forwarded-For")
    if forwarded_for:
        candidates.extend(
            normalize_request_ip_candidate(part)
            for part in str(forwarded_for).split(",")
        )
    forwarded = request.headers.get("Forwarded")
    if forwarded:
        for segment in str(forwarded).split(","):
            for part in segment.split(";"):
                part = part.strip()
                if part.lower().startswith("for="):
                    candidates.append(normalize_request_ip_candidate(part))
    remote = normalize_request_ip_candidate(request.remote_addr)
    if remote:
        candidates.append(remote)
    valid_candidates: list[str] = []
    for candidate in candidates:
        if not candidate:
            continue
        try:
            parsed = ipaddress.ip_address(candidate)
        except ValueError:
            continue
        normalized = str(parsed)
        valid_candidates.append(normalized)
        if parsed.is_global:
            return normalized
    return valid_candidates[0] if valid_candidates else ""


def audit_event_row(row: dict[str, Any]) -> dict[str, Any]:
    return {
        "id": row["id"],
        "eventType": row["event_type"],
        "category": row["category"],
        "actorUserId": row.get("actor_user_id"),
        "actorUsername": row.get("actor_username"),
        "actorRole": row.get("actor_role"),
        "targetType": row.get("target_type"),
        "targetId": row.get("target_id"),
        "summary": row.get("summary"),
        "metadata": redact_sensitive_payload(row.get("metadata") or {}),
        "requestIp": row.get("request_ip"),
        "userAgent": row.get("user_agent"),
        "createdAt": row.get("created_at"),
    }


def api_request_query_payload() -> dict[str, Any]:
    payload: dict[str, Any] = {}
    for key in request.args.keys():
        values = request.args.getlist(key)
        payload[key] = values if len(values) > 1 else (values[0] if values else "")
    return payload


def api_audit_metadata(
    actor: dict[str, Any] | None,
    *,
    command: str,
    request_payload: dict[str, Any] | None = None,
    extra: dict[str, Any] | None = None,
) -> dict[str, Any]:
    actor = actor or {}
    api_token = actor.get("apiToken") or {}
    metadata: dict[str, Any] = {
        "command": command,
        "method": request.method,
        "endpoint": request.path,
        "query": api_request_query_payload(),
        "agent": request.headers.get("X-DiscVault-Agent")
        or request.headers.get("X-MCP-Client")
        or request.headers.get("User-Agent"),
        "tool": request.headers.get("X-DiscVault-MCP-Tool") or command,
        "apiTokenId": api_token.get("id"),
        "apiTokenName": api_token.get("name"),
        "apiTokenScopes": api_token.get("scopes") or [],
        "apiTokenPermissions": api_token.get("permissionKeys") or [],
    }
    if request_payload is not None:
        metadata["request"] = request_payload
    if extra:
        metadata.update(extra)
    return metadata


def audit_api_interaction(
    conn,
    actor: dict[str, Any],
    *,
    command: str,
    event_type: str,
    target_type: str | None = None,
    target_id: Any = None,
    summary: str | None = None,
    request_payload: dict[str, Any] | None = None,
    metadata: dict[str, Any] | None = None,
) -> None:
    audit_event(
        conn,
        event_type=event_type,
        category="api",
        actor=actor,
        target_type=target_type,
        target_id=target_id,
        summary=summary,
        metadata=api_audit_metadata(actor, command=command, request_payload=request_payload, extra=metadata),
    )


def metadata_refresh_jobs(
    conn,
    *,
    movie_id: UUID | None = None,
    status: str = "",
    limit: int = 50,
) -> list[dict[str, Any]]:
    if not table_exists(conn, "background_jobs"):
        return []
    clauses = ["job_type = %s"]
    params: list[Any] = [METADATA_REFRESH_JOB_TYPE]
    if movie_id:
        clauses.append("payload->>'movieId' = %s")
        params.append(str(movie_id))
    if status:
        clauses.append("status = %s")
        params.append(status)
    where = " AND ".join(clauses)
    with conn.cursor() as cur:
        cur.execute(
            f"""
            SELECT
                id,
                job_type,
                status,
                requested_by,
                payload,
                result,
                error,
                created_at,
                started_at,
                finished_at
            FROM background_jobs
            WHERE {where}
            ORDER BY created_at DESC
            LIMIT %s
            """,
            (*params, limit),
        )
        rows = cur.fetchall()
    return [job_row(row) for row in rows]


