PUBLIC_NEXT_PATHS = {
    "/",
    "/app",
    "/app/",
    "/app/import",
    "/app/import/",
    "/app/lists",
    "/app/lists/",
    "/app/notifications",
    "/app/notifications/",
    "/app/profile",
    "/app/profile/",
    "/app/admin",
    "/app/admin/",
    "/ui-preview",
    "/ui-preview/",
    "/api/next/app",
    "/api/next/app/",
    "/api/next/app/import",
    "/api/next/app/import/",
    "/api/next/collection",
    "/api/next/collection/",
    "/api/next/health",
    "/api/next/i18n",
    "/api/next/manifest.json",
    "/api/next/ui-preview",
    "/api/next/ui-preview/",
    "/api/next/migration",
    "/api/next/migration/",
}
PUBLIC_NEXT_PREFIXES = (
    "/.well-known/",
    "/api/auth/",
    "/api/next/auth/",
    "/api/next/assets/",
    "/api/next/i18n/",
    "/api/next/media/assets/",
    "/api/next/media/legacy/",
    "/app/movies/",
    "/app/containers/",
    "/app/people/",
)


def is_public_next_path(path: str) -> bool:
    return path in PUBLIC_NEXT_PATHS or any(path.startswith(prefix) for prefix in PUBLIC_NEXT_PREFIXES)


def register_routes(flask_app: Flask) -> None:
    register_next_auth_routes(
        flask_app,
        connect=connect,
        table_exists=table_exists,
        response=response,
        next_api_error=NextApiError,
    )

    @flask_app.errorhandler(NextApiError)
    def handle_next_error(error: NextApiError):
        return response({"status": "error", "error": str(error)}, error.status_code)

    @flask_app.errorhandler(HTTPException)
    def handle_http_error(error: HTTPException):
        return response(
            {
                "status": "error",
                "error": error.description,
                "path": request.path,
            },
            error.code or 500,
        )

    @flask_app.errorhandler(Exception)
    def handle_unexpected_error(error: Exception):  # pragma: no cover - Flask integration
        flask_app.logger.exception("Unhandled Next API error on %s", request.path)
        return response({"status": "error", "error": str(error), "path": request.path}, 500)

    @flask_app.before_request
    def require_next_auth():
        if not (
            request.path == "/"
            or request.path.startswith(("/app", "/api/next", "/api/auth", "/.well-known"))
        ):
            return None
        if is_public_next_path(request.path):
            return None
        with connect() as conn:
            if not next_auth_effective_enabled(conn, table_exists):
                return None
            if next_auth_current_user(conn):
                return None
        return response(
            {
                "status": "error",
                "error": "Authentication required",
                "auth_required": True,
                "path": request.path,
            },
            401,
        )

    def mcp_proxy_request(path: str = "/mcp"):
        target = f"http://127.0.0.1:6090{path}"
        body_bytes = request.get_data()
        body_json = request.get_json(silent=True) if body_bytes else None
        bearer_actor: dict[str, Any] | None = None
        auth_header = request.headers.get("Authorization", "")
        if auth_header.startswith("Bearer "):
            with connect() as conn:
                bearer_actor = next_auth_current_api_token_user(conn, auth_header[7:])
        headers = {
            key: value
            for key, value in request.headers.items()
            if key.lower()
            in {
                "accept",
                "authorization",
                "content-type",
                "mcp-session-id",
            }
        }
        try:
            proxied = http_requests.request(
                request.method,
                target,
                data=body_bytes,
                headers=headers,
                timeout=60,
            )
        except http_requests.RequestException as exc:
            if bearer_actor:
                with connect() as conn:
                    audit_event(
                        conn,
                        event_type="mcp.request_failed",
                        category="mcp",
                        actor=bearer_actor,
                        target_type="api_access_token",
                        target_id=(bearer_actor.get("apiToken") or {}).get("id"),
                        summary=f"MCP proxy failed: {exc}",
                        metadata=api_audit_metadata(
                            bearer_actor,
                            command=f"mcp.{request.method.lower()}",
                            request_payload=body_json if isinstance(body_json, (dict, list)) else None,
                            extra={
                                "category": "mcp",
                                "mcpPath": path,
                                "proxyError": str(exc),
                            },
                        ),
                    )
            return response(
                {
                    "status": "error",
                    "error": "MCP server is not reachable",
                    "detail": str(exc),
                },
                503,
            )
        if bearer_actor:
            messages = body_json if isinstance(body_json, list) else ([body_json] if isinstance(body_json, dict) else [])
            methods: list[str] = []
            tools: list[str] = []
            for msg in messages:
                if not isinstance(msg, dict):
                    continue
                method = clean_text(msg.get("method"))
                if method:
                    methods.append(method)
                params = msg.get("params")
                if isinstance(params, dict):
                    tool_name = clean_text(params.get("name"))
                    if tool_name:
                        tools.append(tool_name)
            command = tools[0] if tools else (methods[0] if methods else f"mcp.{request.method.lower()}")
            metadata = api_audit_metadata(
                bearer_actor,
                command=command,
                request_payload=body_json if isinstance(body_json, (dict, list)) else None,
                extra={
                    "category": "mcp",
                    "mcpPath": path,
                    "mcpMethods": methods,
                    "mcpTools": tools,
                    "mcpSessionId": request.headers.get("Mcp-Session-Id") or proxied.headers.get("Mcp-Session-Id"),
                    "responseStatus": proxied.status_code,
                    "responseContentType": proxied.headers.get("Content-Type"),
                },
            )
            with connect() as conn:
                audit_event(
                    conn,
                    event_type="mcp.request",
                    category="mcp",
                    actor=bearer_actor,
                    target_type="api_access_token",
                    target_id=(bearer_actor.get("apiToken") or {}).get("id"),
                    summary=f"MCP {command} -> {proxied.status_code}",
                    metadata=metadata,
                )
        response_headers = {}
        for header in ("Content-Type", "Mcp-Session-Id"):
            value = proxied.headers.get(header)
            if value:
                response_headers[header] = value
        return Response(proxied.content, status=proxied.status_code, headers=response_headers)

    @flask_app.route("/mcp", methods=["GET", "POST", "DELETE"])
    def mcp_proxy():
        return mcp_proxy_request("/mcp")

    @flask_app.get("/mcp-health")
    def mcp_health_proxy():
        return mcp_proxy_request("/health")

    @flask_app.get("/api/next/health")
    def health():
        with connect() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    SELECT
                        current_database() AS database,
                        current_user AS user,
                        version() AS postgres_version,
                        now() AS checked_at
                    """
                )
                db = cur.fetchone()
            migrations = migration_overview(conn)
            artwork_purge = {"purgedLinks": 0, "purgedAssets": 0, "purgedFiles": 0}
            if migrations.get("state") == "ready":
                with conn.transaction():
                    artwork_purge = purge_expired_artwork_trash(conn)
        migration_state = migrations["state"]
        is_ready = migration_state == "ready"
        return response(
            {
                "status": "ok" if is_ready else "degraded",
                "service": "discvault-next-api",
                "version": build_version(),
                "sha": build_sha(),
                "database": db,
                "migrations": migrations,
                "maintenance": {"artworkTrash": artwork_purge},
            },
            200 if is_ready else 503,
        )

    @flask_app.get("/manifest.json")
    @flask_app.get("/api/next/manifest.json")
    def next_pwa_manifest():
        result = jsonify(pwa_manifest_payload())
        result.headers["Cache-Control"] = "no-store, no-cache, must-revalidate, max-age=0"
        return result

    @flask_app.get("/service-worker.js")
    def next_service_worker():
        path = next_frontend_dir() / "service-worker.js"
        if not path.exists() or not path.is_file():
            raise NextApiError("Service worker not found", 404)
        result = send_file(path, mimetype="application/javascript")
        result.headers["Cache-Control"] = "no-store, no-cache, must-revalidate, max-age=0"
        return result

    @flask_app.get("/api/next/assets/<path:asset_name>")
    def next_frontend_asset(asset_name: str):
        safe_name = Path(asset_name).name
        if safe_name != asset_name or safe_name not in PWA_ICON_ASSETS:
            raise NextApiError("Asset not found", 404)
        path = next_frontend_dir() / safe_name
        if not path.exists() or not path.is_file():
            raise NextApiError("Asset not found", 404)
        return send_file(path, mimetype=mimetypes.guess_type(path.name)[0] or "application/octet-stream")

    @flask_app.get("/api/next/flags/<path:flag_name>")
    def next_frontend_flag(flag_name: str):
        safe_name = Path(flag_name).name
        if safe_name != flag_name or not re.fullmatch(r"[a-z]{2}\.svg", safe_name):
            raise NextApiError("Flag not found", 404)
        path = next_frontend_dir() / "flags" / safe_name
        if not path.exists() or not path.is_file():
            raise NextApiError("Flag not found", 404)
        return send_file(path, mimetype="image/svg+xml")

