    @flask_app.patch("/api/next/movies/<movie_id>")
    def update_movie(movie_id: str):
        movie_uuid = parse_uuid(movie_id, "movieId")
        if not movie_uuid:
            raise NextApiError("movieId is required", 400)
        body = request.get_json(silent=True) or {}
        if not isinstance(body, dict):
            raise NextApiError("Movie request body must be an object", 400)
        with connect() as conn:
            actor = require_next_permission(conn, "collection.edit_all")
            if not table_exists(conn, "movies"):
                raise NextApiError("Movie table is not available", 503)
            existing = movie_entity(conn, movie_uuid)
            if not existing:
                raise NextApiError("Movie not found", 404)
            if not actor_can_edit_visible_movie(conn, actor, existing):
                raise NextApiError("Permission required: collection.edit_all", 403)
            payload = movie_update_payload(body, existing=existing)
            receiver_proposal = movie_edit_receiver_proposal(existing, payload)
            receiver_summary: dict[str, Any] = {"skipped": True, "reason": "no_public_receiver_fields_changed"}
            revision = 0
            entity = existing
            with conn.transaction():
                with conn.cursor() as cur:
                    cur.execute(
                        """
                        UPDATE movies
                        SET title=%s,
                            sort_title=%s,
                            original_title=%s,
                            year=%s,
                            barcode=%s,
                            release_date=%s,
                            format=%s,
                            edition=%s,
                            country=%s,
                            language=%s,
                            overview=%s,
                            notes=%s,
                            location=%s,
                            updated_at=now()
                        WHERE id=%s
                        """,
                        (
                            payload["title"],
                            payload["sort_title"],
                            payload["original_title"],
                            payload["year"],
                            payload["barcode"],
                            payload["release_date"],
                            payload["format"],
                            payload["edition"],
                            payload["country"],
                            payload["language"],
                            payload["overview"],
                            payload["notes"],
                            payload["location"],
                            movie_uuid,
                        ),
                    )
                    revision = next_revision(conn) if table_exists(conn, "sync_state") else 0
                    entity = movie_entity(conn, movie_uuid) or {}
                    if revision and table_exists(conn, "sync_changes"):
                        sync_change(
                            conn,
                            revision=revision,
                            entity_type="movie",
                            entity_id=str(movie_uuid),
                            operation="upsert",
                            payload={
                                "entity": entity,
                                "clientId": "next-app",
                                "clientMutationId": f"edit-movie-{uuid.uuid4()}",
                                "actor": actor_job_payload(actor),
                            },
                        )
            detail = movie_detail_entity(conn, movie_uuid)
            if receiver_proposal:
                try:
                    receiver_summary = push_metadata_to_receivers(
                        conn,
                        movie_id=movie_uuid,
                        movie=entity or movie_entity(conn, movie_uuid) or {},
                        preview={
                            "movie": entity or {},
                            "proposal": receiver_proposal,
                            "results": [],
                        },
                        applied={
                            "changed": True,
                            "revision": revision,
                            "applied": {
                                "movieUpdates": receiver_proposal.get("movieUpdates") or {},
                                "metadataUpdates": receiver_proposal.get("metadataUpdates") or {},
                                "technicalUpdates": {},
                                "mediaUpdates": {},
                                "identifiers": {},
                                "provenance": len(receiver_proposal.get("provenance") or []),
                            },
                        },
                        actor=actor,
                    )
                except Exception as exc:
                    receiver_summary = {"status": "error", "error": str(exc)}
            audit_event(
                conn,
                event_type="movie.updated",
                category="admin",
                actor=actor,
                target_type="movie",
                target_id=movie_uuid,
                summary=f"Updated movie {payload['title']}",
                metadata={"title": payload["title"], "barcode": payload["barcode"]},
            )
            if receiver_proposal:
                audit_event(
                    conn,
                    event_type="metadata.receiver_pushed",
                    category="metadata",
                    actor=actor,
                    target_type="movie",
                    target_id=movie_uuid,
                    summary=f"Pushed local movie edit to receiver plugins for {payload['title']}",
                    metadata={
                        "movieId": str(movie_uuid),
                        "title": payload["title"],
                        "barcode": payload["barcode"],
                        "changedFields": sorted((receiver_proposal.get("metadataUpdates") or {}).keys()),
                        "receiverSummary": receiver_summary,
                    },
                )
        return response({"status": "ok", "detail": detail, "receiverSummary": receiver_summary})

