    @flask_app.post("/api/next/import/source/upload")
    def upload_import_source_file():
        if request.content_length and request.content_length > MAX_IMPORT_UPLOAD_BYTES:
            raise NextApiError("Import file is too large", 413)
        requested_plugin_id = clean_text(
            request.form.get("importSourceId")
            or request.form.get("pluginId")
            or request.args.get("importSourceId")
            or request.args.get("pluginId")
        )
        upload_id = uuid.uuid4().hex
        upload_dir = import_upload_root() / upload_id
        upload_path, filename, size_bytes = store_import_upload(upload_dir)
        source_path = upload_path
        archive = upload_path.suffix.lower() == ".zip"
        if archive:
            source_path = extract_import_upload_archive(upload_path, upload_dir)
        with connect() as conn:
            actor = require_next_permission(conn, "collection.import")
            plugins = import_source_plugins(conn)
            if requested_plugin_id:
                plugin = import_source_plugin_by_id(conn, requested_plugin_id)
                if not plugin:
                    raise NextApiError(f"Import source plugin is not available: {requested_plugin_id}", 409)
                plugins = [plugin]
            candidates, preview = import_upload_candidates(
                conn,
                source_path=source_path,
                plugins=plugins,
                actor=actor,
            )
            selected_source_id = None
            if preview and isinstance(preview.get("source"), dict):
                selected_source_id = preview["source"].get("pluginId")
            recognized = bool(preview and selected_source_id)
            if recognized:
                audit_event(
                    conn,
                    event_type="import_source.uploaded",
                    category="import",
                    actor=actor,
                    target_type="plugin",
                    target_id=selected_source_id,
                    summary=f"Uploaded import file {filename}",
                    metadata={
                        "fileName": filename,
                        "sizeBytes": size_bytes,
                        "sourcePath": str(source_path),
                        "pluginId": selected_source_id,
                        "archive": archive,
                    },
                )
        return response(
            {
                "status": "ok",
                "recognized": recognized,
                "selectedSourceId": selected_source_id,
                "preview": preview,
                "candidates": candidates,
                "upload": {
                    "id": upload_id,
                    "fileName": filename,
                    "sizeBytes": size_bytes,
                    "uploadedFile": str(upload_path),
                    "sourcePath": str(source_path),
                    "archive": archive,
                },
            }
        )

    @flask_app.post("/api/next/import/source/start")
    def start_import_source():
        body = request.get_json(silent=True) or {}
        if not isinstance(body, dict):
            raise NextApiError("Import source start body must be an object", 400)
        plugin_id = clean_text(body.get("importSourceId") or body.get("import_source_id") or body.get("pluginId"))
        if not plugin_id:
            raise NextApiError("importSourceId is required", 400)
        source_path = clean_text(body.get("sourcePath") or body.get("source_path") or body.get("path"))
        column_mapping = normalize_import_column_mapping(body.get("columnMapping") or body.get("column_mapping"))
        import_review = normalize_import_review(body.get("importReview") or body.get("import_review"))
        options = {
            "includeSecurity": False,
            "includePersonal": parse_bool_value(body.get("includePersonal", body.get("include_personal")), default=True),
            "ownerUsername": clean_text(body.get("ownerUsername") or body.get("owner_username")),
            "importMediaReferences": parse_bool_value(
                body.get("importMediaReferences", body.get("import_media_references")),
                default=True,
            ),
            "sourcePath": source_path,
            "columnMapping": column_mapping,
            "importReview": import_review,
        }
        inspect_payload = import_source_payload_for_path(plugin_id, source_path, column_mapping)
        with connect() as conn:
            actor = require_next_permission(conn, "collection.import")
            plugin = import_source_plugin_by_id(conn, plugin_id)
            if not plugin:
                raise NextApiError(f"Import source plugin is not available: {plugin_id}", 409)
            selected_source, execution = inspect_import_source_plugin(conn, plugin, inspect_payload, actor)
            if execution.get("status") != "ok":
                raise NextApiError(
                    f"Import source inspection failed: {execution.get('error') or execution.get('state')}",
                    502,
                )
            if not selected_source.get("found") or not selected_source.get("readable"):
                raise NextApiError(f"Import source is not ready: {plugin_id}", 409)
            job_type, payload, import_plan = plan_migration_import_job(
                conn,
                plugin_id=plugin_id,
                source=selected_source,
                options=options,
                actor=actor,
            )
            if job_type != PLUGIN_EXECUTION_JOB_TYPE:
                raise NextApiError(
                    "This source is a migration source. Use the migration wizard to start it.",
                    409,
                )
            with conn.transaction():
                job = create_background_job(conn, job_type=job_type, payload=payload)
                audit_event(
                    conn,
                    event_type="import_source.started",
                    category="import",
                    actor=actor,
                    target_type="background_job",
                    target_id=job.get("id"),
                    summary=f"Started import source {plugin.get('name') or plugin_id}",
                    metadata={
                        "jobType": job_type,
                        "pluginId": plugin_id,
                        "sourceKind": selected_source.get("sourceKind"),
                        "sourcePath": selected_source.get("sourcePath") or source_path,
                        "options": options,
                    },
                )
        return response({"status": "ok", "job": job, "importPlan": import_plan}, 201)

